/* Community chat, complete (round 37), run after parts 81 and 83. `community_chat_settings` is one row per community for what its admins set in Settings, Chat: who may message whom (dm_policy everyone, staff or off), who may start a group (groups_policy members, staff or off), whether files and pictures can be sent, whether a phone's banner shows the words of a message (push_previews), and the chat rules a member accepts once before their first message (rules, rules_version; a new version asks again). `community_spaces.slow_mode_seconds` is a chat channel's own slow mode, 0 to 3600. `community_members` gets the member's own choice of who may message them (chat_dms everyone, staff or nobody), the rules version they accepted and when, and a chat only mute or ban set by a moderator (chat_muted_until, chat_banned_at, with who and why), so a member can be kept out of chat and still read the feed. `community_chat_groups`, `community_chat_group_members` and `community_chat_group_messages` are group chats made inside a community, with their people (owner or member, each with their own read mark) and messages; `public.community_in_group` says whether the signed in person is an active member of the community and in the group, and is the only way their rows are read. Messages in channels, conversations and groups take `client_id`, the sender's own id for a message, unique per author, so a send retried after a dropped connection is written once; direct messages also take `attachments` and `reply_to_id`. `community_chat_prefs` is a person's mute and notification choice for one channel, conversation or group, and `community_member_blocks` who a person has blocked (no messages either way). Reports can name a group message. `public.community_chat_topic_ok` lets a member join the typing channel of a chat they may read (realtime broadcast with private channels), added to realtime.messages when this role may. The three group tables join the supabase_realtime publication. RLS is on for every new table; members read only groups they are in, everything else is the server's. No rows change. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.community_chat_settings (community_id uuid PRIMARY KEY REFERENCES public.communities(id) ON DELETE CASCADE, dm_policy text NOT NULL DEFAULT 'everyone', groups_policy text NOT NULL DEFAULT 'members', attachments_enabled boolean NOT NULL DEFAULT true, push_previews boolean NOT NULL DEFAULT true, rules text NOT NULL DEFAULT '', rules_version integer NOT NULL DEFAULT 0, updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_chat_settings_dm_policy CHECK (dm_policy IN ('everyone', 'staff', 'off')), CONSTRAINT community_chat_settings_groups_policy CHECK (groups_policy IN ('members', 'staff', 'off')), CONSTRAINT community_chat_settings_rules_len CHECK (char_length(rules) <= 4000), CONSTRAINT community_chat_settings_rules_version CHECK (rules_version >= 0));
ALTER TABLE public.community_spaces ADD COLUMN IF NOT EXISTS slow_mode_seconds integer NOT NULL DEFAULT 0;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_spaces_slow_mode_range') THEN ALTER TABLE public.community_spaces ADD CONSTRAINT community_spaces_slow_mode_range CHECK (slow_mode_seconds BETWEEN 0 AND 3600) NOT VALID; END IF; END $do$;
ALTER TABLE public.community_members ADD COLUMN IF NOT EXISTS chat_dms text NOT NULL DEFAULT 'everyone', ADD COLUMN IF NOT EXISTS chat_rules_version integer, ADD COLUMN IF NOT EXISTS chat_rules_accepted_at timestamptz, ADD COLUMN IF NOT EXISTS chat_muted_until timestamptz, ADD COLUMN IF NOT EXISTS chat_banned_at timestamptz, ADD COLUMN IF NOT EXISTS chat_restricted_by uuid, ADD COLUMN IF NOT EXISTS chat_restriction_reason text;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_members_chat_dms_check') THEN ALTER TABLE public.community_members ADD CONSTRAINT community_members_chat_dms_check CHECK (chat_dms IN ('everyone', 'staff', 'nobody')) NOT VALID; END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_members_chat_reason_len') THEN ALTER TABLE public.community_members ADD CONSTRAINT community_members_chat_reason_len CHECK (chat_restriction_reason IS NULL OR char_length(chat_restriction_reason) <= 500) NOT VALID; END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.community_chat_groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, name text NOT NULL, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, member_count integer NOT NULL DEFAULT 0, last_message_at timestamptz, last_author_id uuid, last_body text NOT NULL DEFAULT '', archived_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT community_chat_groups_name_len CHECK (char_length(name) BETWEEN 1 AND 80), CONSTRAINT community_chat_groups_last_body_len CHECK (char_length(last_body) <= 200), CONSTRAINT community_chat_groups_member_count CHECK (member_count >= 0));
CREATE INDEX IF NOT EXISTS community_chat_groups_community_idx ON public.community_chat_groups (community_id, last_message_at DESC);
CREATE TABLE IF NOT EXISTS public.community_chat_group_members (group_id uuid NOT NULL REFERENCES public.community_chat_groups(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'member', added_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, last_read_at timestamptz, joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (group_id, user_id), CONSTRAINT community_chat_group_members_role CHECK (role IN ('owner', 'member')));
CREATE INDEX IF NOT EXISTS community_chat_group_members_user_idx ON public.community_chat_group_members (user_id, community_id);
CREATE TABLE IF NOT EXISTS public.community_chat_group_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES public.community_chat_groups(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, author_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, kind text NOT NULL DEFAULT 'message', body text NOT NULL DEFAULT '', attachments jsonb NOT NULL DEFAULT '[]'::jsonb, reply_to_id uuid REFERENCES public.community_chat_group_messages(id) ON DELETE SET NULL, client_id text, status text NOT NULL DEFAULT 'published', created_at timestamptz NOT NULL DEFAULT now(), edited_at timestamptz, deleted_at timestamptz, CONSTRAINT community_chat_group_messages_kind CHECK (kind IN ('message', 'event')), CONSTRAINT community_chat_group_messages_status CHECK (status IN ('published', 'deleted', 'removed')), CONSTRAINT community_chat_group_messages_body_len CHECK (char_length(body) <= 4000), CONSTRAINT community_chat_group_messages_client_len CHECK (client_id IS NULL OR char_length(client_id) BETWEEN 8 AND 64), CONSTRAINT community_chat_group_messages_attachments_array CHECK (jsonb_typeof(attachments) = 'array'));
CREATE INDEX IF NOT EXISTS community_chat_group_messages_group_idx ON public.community_chat_group_messages (group_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS community_chat_group_messages_client_key ON public.community_chat_group_messages (author_id, client_id) WHERE client_id IS NOT NULL;
ALTER TABLE public.community_messages ADD COLUMN IF NOT EXISTS client_id text;
CREATE UNIQUE INDEX IF NOT EXISTS community_messages_client_key ON public.community_messages (author_id, client_id) WHERE client_id IS NOT NULL;
ALTER TABLE public.community_direct_messages ADD COLUMN IF NOT EXISTS attachments jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN IF NOT EXISTS reply_to_id uuid REFERENCES public.community_direct_messages(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS client_id text;
CREATE UNIQUE INDEX IF NOT EXISTS community_direct_messages_client_key ON public.community_direct_messages (author_id, client_id) WHERE client_id IS NOT NULL;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_messages_client_len') THEN ALTER TABLE public.community_messages ADD CONSTRAINT community_messages_client_len CHECK (client_id IS NULL OR char_length(client_id) BETWEEN 8 AND 64) NOT VALID; END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'community_direct_messages_client_len') THEN ALTER TABLE public.community_direct_messages ADD CONSTRAINT community_direct_messages_client_len CHECK (client_id IS NULL OR char_length(client_id) BETWEEN 8 AND 64) NOT VALID; END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.community_chat_prefs (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, community_id uuid NOT NULL REFERENCES public.communities(id) ON DELETE CASCADE, chat_type text NOT NULL, chat_id uuid NOT NULL, notify text NOT NULL DEFAULT 'default', muted_until timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, chat_type, chat_id), CONSTRAINT community_chat_prefs_type CHECK (chat_type IN ('space', 'dm', 'group')), CONSTRAINT community_chat_prefs_notify CHECK (notify IN ('default', 'all', 'mentions', 'none')));
CREATE INDEX IF NOT EXISTS community_chat_prefs_chat_idx ON public.community_chat_prefs (chat_type, chat_id, notify);
CREATE TABLE IF NOT EXISTS public.community_member_blocks (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, blocked_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, blocked_id), CONSTRAINT community_member_blocks_not_self CHECK (user_id <> blocked_id));
CREATE INDEX IF NOT EXISTS community_member_blocks_blocked_idx ON public.community_member_blocks (blocked_id);
ALTER TABLE public.community_reports DROP CONSTRAINT IF EXISTS community_reports_target_check, ADD CONSTRAINT community_reports_target_check CHECK (target_type IN ('post', 'comment', 'member', 'message', 'group_message')) NOT VALID;
CREATE OR REPLACE FUNCTION public.community_in_group(p_group uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT EXISTS (SELECT 1 FROM public.community_chat_group_members gm JOIN public.community_chat_groups g ON g.id = gm.group_id JOIN public.community_members m ON m.community_id = g.community_id AND m.user_id = gm.user_id JOIN public.communities k ON k.id = g.community_id WHERE gm.group_id = p_group AND gm.user_id = auth.uid() AND g.archived_at IS NULL AND m.status = 'active' AND m.banned_at IS NULL AND m.chat_banned_at IS NULL AND k.deleted_at IS NULL AND k.suspended_at IS NULL AND k.chat_enabled) $f$;
CREATE OR REPLACE FUNCTION public.community_chat_topic_ok(p_topic text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF auth.uid() IS NULL OR p_topic IS NULL THEN RETURN false; END IF; IF p_topic ~ '^chat:space:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN public.community_can_read_space(substr(p_topic, 12)::uuid); END IF; IF p_topic ~ '^chat:dm:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN public.community_in_conversation(substr(p_topic, 9)::uuid); END IF; IF p_topic ~ '^chat:group:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN public.community_in_group(substr(p_topic, 12)::uuid); END IF; RETURN false; END $f$;
CREATE OR REPLACE FUNCTION public.community_chat_group_count() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF TG_OP = 'INSERT' THEN UPDATE public.community_chat_groups SET member_count = member_count + 1, updated_at = now() WHERE id = NEW.group_id; RETURN NEW; END IF; UPDATE public.community_chat_groups SET member_count = greatest(member_count - 1, 0), updated_at = now() WHERE id = OLD.group_id; RETURN OLD; END $f$;
DROP TRIGGER IF EXISTS community_chat_group_members_count ON public.community_chat_group_members;
CREATE TRIGGER community_chat_group_members_count AFTER INSERT OR DELETE ON public.community_chat_group_members FOR EACH ROW EXECUTE FUNCTION public.community_chat_group_count();
ALTER TABLE public.community_chat_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_chat_groups ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_chat_group_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_chat_group_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_chat_prefs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_member_blocks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_chat_settings, public.community_chat_groups, public.community_chat_group_members, public.community_chat_group_messages, public.community_chat_prefs, public.community_member_blocks FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.community_chat_groups, public.community_chat_group_members, public.community_chat_group_messages TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.community_chat_settings, public.community_chat_groups, public.community_chat_group_members, public.community_chat_group_messages, public.community_chat_prefs, public.community_member_blocks TO service_role;
REVOKE ALL ON FUNCTION public.community_in_group(uuid) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.community_chat_topic_ok(text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.community_chat_group_count() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.community_in_group(uuid) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.community_chat_topic_ok(text) TO authenticated, service_role;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib members read their groups" ON public.community_chat_groups; CREATE POLICY "storelib members read their groups" ON public.community_chat_groups FOR SELECT TO authenticated USING (public.community_in_group(id)); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib members read their group people" ON public.community_chat_group_members; CREATE POLICY "storelib members read their group people" ON public.community_chat_group_members FOR SELECT TO authenticated USING (public.community_in_group(group_id)); END $do$;
DO $do$ BEGIN DROP POLICY IF EXISTS "storelib members read their group messages" ON public.community_chat_group_messages; CREATE POLICY "storelib members read their group messages" ON public.community_chat_group_messages FOR SELECT TO authenticated USING (public.community_in_group(group_id)); END $do$;
DO $do$ BEGIN IF to_regclass('realtime.messages') IS NULL OR to_regprocedure('realtime.topic()') IS NULL THEN RAISE NOTICE 'community chat: realtime.messages is not here, typing shows nothing and every message still arrives.'; RETURN; END IF; BEGIN EXECUTE 'DROP POLICY IF EXISTS "storelib chat typing read" ON realtime.messages'; EXECUTE 'CREATE POLICY "storelib chat typing read" ON realtime.messages FOR SELECT TO authenticated USING (realtime.messages.extension = ''broadcast'' AND public.community_chat_topic_ok(realtime.topic()))'; EXECUTE 'DROP POLICY IF EXISTS "storelib chat typing send" ON realtime.messages'; EXECUTE 'CREATE POLICY "storelib chat typing send" ON realtime.messages FOR INSERT TO authenticated WITH CHECK (realtime.messages.extension = ''broadcast'' AND public.community_chat_topic_ok(realtime.topic()))'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'community chat: this role may not add policies to realtime.messages, typing shows nothing and every message still arrives.'; END; END $do$;
DO $do$ DECLARE v_owner oid; v_table text; BEGIN SELECT pubowner INTO v_owner FROM pg_publication WHERE pubname = 'supabase_realtime'; IF NOT FOUND THEN RAISE NOTICE 'community chat: there is no supabase_realtime publication, group messages show when the chat asks again.'; RETURN; END IF; IF NOT pg_has_role(current_user, v_owner, 'MEMBER') THEN RAISE NOTICE 'community chat: this role does not own supabase_realtime, add community_chat_groups, community_chat_group_members and community_chat_group_messages to it in Database, Publications.'; RETURN; END IF; FOREACH v_table IN ARRAY ARRAY['community_chat_groups', 'community_chat_group_members', 'community_chat_group_messages', 'community_messages', 'community_conversations', 'community_direct_messages'] LOOP IF to_regclass('public.' || v_table) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = v_table) THEN EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', v_table); END IF; END LOOP; END $do$;
notify pgrst, 'reload schema';
